const UPDATE_CHECK_INTERVAL_MS = 60 * 60 * 1000;
const RUNNER_SELF_RESTART_FILES = new Set([
'host/muse-runner.mjs',
'kernel/shared/constants.js',
]);
function writeLastUpdateRecord(dataDir, record) {
const filePath = path.join(dataDir, 'last-update.json');
const payload = {
checked_at: new Date().toISOString(),
localVersion: record.localVersion ?? null,
remoteVersion: record.remoteVersion ?? null,
updated: Boolean(record.updated),
version: record.version ?? null,
backupDir: record.backupDir ?? null,
error: record.error ?? null,
};
try {
fs.writeFileSync(filePath, ${JSON.stringify(payload, null, 2)}\n, 'utf8');
} catch {
// 状态文件写入失败不影响主循环
}
}
function hasPendingTasks(dataDir) {
const pendingDir = path.join(dataDir, 'tasks', 'pending');
try {
const entries = fs.readdirSync(pendingDir);
return entries.some((name) => !name.startsWith('.'));
} catch {
return false;
}
}
function isBridgeReadyForUpdate(status) {
if (!status || !status.up) return false;
if (Array.isArray(status.extensions)) return status.extensions.length > 0;
return Number(status.extensions) > 0 || status.extensions === true;
}
function needsRunnerSelfRestart(applyResult) {
const changed = [
...(applyResult?.updated || []),
...(applyResult?.added || []),
];
return changed.some((relPath) =>
RUNNER_SELF_RESTART_FILES.has(String(relPath).replace(/\/g, '/')),
);
}
function spawnDetachedSelf() {
const child = spawn(process.execPath, process.argv.slice(1), {
cwd: process.cwd(),
detached: true,
stdio: 'ignore',
windowsHide: true,
});
child.unref();
}
async function runIdleOnlineUpdate({
dataDir,
installDir,
bridge,
log,
cleanupBeforeExit,
}) {
const config = loadConfig(dataDir);
const token = config?.github_token;
if (!token) {
return { checked: false };
}
// 查更新前确认桥是通的、插件连着
let status;
try {
status = await bridge.status();
} catch (err) {
log(在线更新跳过：无法获取桥状态（${err?.message || err}）);
return { checked: false };
}
if (!isBridgeReadyForUpdate(status)) {
log('在线更新跳过：桥未就绪或插件未连接');
return { checked: false };
}
let checkRes;
try {
checkRes = await checkForUpdate({ token, installDir });
} catch (err) {
const msg = err?.message || String(err);
log(在线更新检查失败：${msg});
writeLastUpdateRecord(dataDir, { error: msg });
return { checked: true, updated: false };
}
const localVersion = checkRes?.localVersion ?? status.diskVersion ?? status.version ?? null;
const remoteVersion = checkRes?.remoteVersion ?? null;
const hasUpdate = Boolean(
checkRes?.hasUpdate ?? checkRes?.updateAvailable ?? checkRes?.available,
);
if (!hasUpdate) {
log(在线更新检查完成：已是最新版本 ${localVersion ?? ''}.trim());
writeLastUpdateRecord(dataDir, {
localVersion,
remoteVersion,
updated: false,
version: localVersion,
});
return { checked: true, updated: false };
}
log(发现新版本 ${remoteVersion}（当前 ${localVersion}），开始规划更新);
let applyRes;
try {
await planUpdate({ token, installDir });
const stagingDir = path.join(
path.dirname(installDir),
'.yixiubridge-update-staging',
);
applyRes = await applyUpdate({ token, installDir, stagingDir });
} catch (err) {
const msg = err?.message || String(err);
log(在线更新应用失败（文件未改动）：${msg});
writeLastUpdateRecord(dataDir, {
localVersion,
remoteVersion,
updated: false,
version: localVersion,
error: msg,
});
return { checked: true, updated: false };
}
const targetVersion = applyRes.version || remoteVersion;
let restartRes;
try {
restartRes = await restartBridge({
installDir,
expectedVersion: targetVersion,
timeoutMs: 60_000,
});
} catch (err) {
restartRes = { ok: false, skipped: false, error: err?.message || String(err) };
}
if (restartRes.skipped) {
log(在线更新已写入 ${targetVersion}（${restartRes.reason}，不自动重启桥）);
writeLastUpdateRecord(dataDir, {
localVersion,
remoteVersion,
updated: true,
version: targetVersion,
backupDir: applyRes.backupDir,
});
} else if (!restartRes.ok) {
const errMsg = 新桥启动验证失败：${restartRes.error};
log(在线更新回滚：${errMsg});
try {
await rollback({
installDir,
backupDir: applyRes.backupDir,
addedFiles: applyRes.added || [],
});
startBridgeDetached(installDir);
const oldReady = await waitForBridgeReady({ timeoutMs: 30_000 });
if (oldReady.ok) {
log(在线更新回滚完成：旧桥已恢复运行（${oldReady.status?.version ?? localVersion}）);
} else {
log(在线更新回滚警告：旧桥拉起后未在 30 秒内就绪（${oldReady.error}）);
}
} catch (rbErr) {
log(在线更新回滚异常：${rbErr?.message || rbErr});
}
writeLastUpdateRecord(dataDir, {
localVersion,
remoteVersion,
updated: false,
version: localVersion,
backupDir: applyRes.backupDir,
error: errMsg,
});
return { checked: true, updated: false };
} else {
log(在线更新成功：已升级至 ${targetVersion} 并重启桥);
writeLastUpdateRecord(dataDir, {
localVersion,
remoteVersion,
updated: true,
version: targetVersion,
backupDir: applyRes.backupDir,
});
}
// 若改动涉及 runner 自身或共享常量，释放锁与心跳后拉起新进程并退出
if (needsRunnerSelfRestart(applyRes)) {
log('检测到 runner 核心文件已更新，正在释放锁并重启 runner');
cleanupBeforeExit();
spawnDetachedSelf();
process.exit(0);
}
return { checked: true, updated: true };
}
