// 在 runRunner 中创建 bridge caller、lock/heartbeat 与清理函数之后，增加状态变量：
const installDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
let isUpdating = false;
let isAsking = false;
let lastUpdateCheckAt = 0;
// 统一的清理函数（供 SIGINT/SIGTERM 和 runner 自重启复用，确保删锁、删心跳、清定时器）
const cleanupRunnerResources = () => {
if (loopTimer) clearInterval(loopTimer);
if (heartbeatTimer) clearInterval(heartbeatTimer);
try { fs.unlinkSync(lockFile); } catch {}
try { fs.unlinkSync(heartbeatFile); } catch {}
};
// 将原主循环 tick 改为如下结构（更新期间不取新任务；无待处理任务且无正在问的任务时，每小时最多查一次更新）：
const tick = async () => {
if (isUpdating || isAsking) return;
let processed = false;
isAsking = true;
try {
processed = Boolean(await processOneTask(/* 保持原有参数 */));
} finally {
isAsking = false;
}
// 只有在空闲（本轮没处理任务、pending 为空、没有正在问的任务）且距上次检查满 1 小时才查更新
const now = Date.now();
if (
!processed &&
!isAsking &&
!hasPendingTasks(dataDir) &&
now - lastUpdateCheckAt >= UPDATE_CHECK_INTERVAL_MS
) {
isUpdating = true;
try {
const res = await runIdleOnlineUpdate({
dataDir,
installDir,
bridge,
log,
cleanupBeforeExit: cleanupRunnerResources,
});
if (res.checked) {
lastUpdateCheckAt = Date.now();
}
} finally {
isUpdating = false;
}
}
};
=== END ===
设计要点与接入注意事项：
严格空闲与互斥：用 isUpdating 和 isAsking 两个标志把任务执行和在线更新彻底隔离，更新期间 tick() 直接返回，确保不取新任务、不丢 tasks/pending 里的文件；只有真正发起过 checkForUpdate 才推进 lastUpdateCheckAt，避免桥临时离线导致空等一整小时。
安全杀进程与兜底回滚：bridge-restart.mjs 先用 netstat -ano 精确匹配 LISTENING 且端口 :8765，再用 tasklist 校验映像名是 node.exe 才 taskkill，避免误杀；新桥 60 秒内版本不对就自动 rollback 并拉起旧桥。
接入时注意对齐的 3 个点：确认 checkForUpdate 返回字段名（代码里已兼容 hasUpdate / updateAvailable / available）、确认 processOneTask 在无任务时返回 falsy 值、以及 cleanupRunnerResources 中绑定的 loopTimer / heartbeatTimer / lockFile / heartbeatFile 变量名与 runRunner 现有命名一致。
自重启防双开：needsRunnerSelfRestart 统一把路径分隔符转成 / 避免 Windows 反斜杠漏判，且严格按「清定时器 → 删锁与心跳 → detached 拉起新进程 → process.exit(0)」顺序执行。
